import { defineConfig } from 'orval';

/**
 * Generates the typed API client from the OpenAPI contract (the single source
 * of truth). Never edit src/services/api/generated by hand: run
 * `npm run api:generate`. CI fails if the committed output is out of date.
 */
export default defineConfig({
  meridian: {
    input: {
      target: '../../packages/api-contract/spec/openapi.yaml',
    },
    output: {
      mode: 'tags-split',
      target: 'src/services/api/generated/endpoints',
      schemas: 'src/services/api/generated/model',
      client: 'axios-functions',
      clean: true,
      override: {
        mutator: {
          path: 'src/services/api/http-client.ts',
          name: 'apiRequest',
        },
      },
    },
  },
});
